/// <summary>
/// Example UPSPricingAttribute of table <c>RetailInventTable</c> field lifeFrom.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeRetailInventTableLifeFrom extends UPSPricingAttributeRetailInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(RetailInventTable, lifeFrom);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Date);
    RetailInventTable retailInventTable;
    while select lifeFrom from retailInventTable
        group by lifeFrom
    {
        ret.add(retailInventTable.lifeFrom);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(RetailInventTable, lifeFrom));
    qbr.value(queryValue(_value));
}
